mapper.select:
select
*
from
scm_purchase_order
where
bool_delete_enum = 0

    and  purchase_type = #{purchaseType}


    and  material_type = #{materialType}


    and purchase_status = #{purchaseStatus}


    and serial_number like CONCAT('%', #{serialNumber},'%')


    
        and create_time > #{createTime[0]}
    
    
        and create_time < #{createTime[1]}
    


    and settlement_status = #{settlementStatus}


    and supplier_id = #{supplierId}


    and branch_company_id = #{branchCompanyId}


    and (last_operator_name like CONCAT('%', #{operatorName},'%') or applicant_name like
    CONCAT('%',#{operatorName},'%'))


    and find_in_set(#{projectId},project_ids)

SELECT temp.supplier_id, temp.supplier_name, SUM( temp.amount ) AS amount, IFNULL(SUM( temp.settlement_amount ),0) AS settlement_amount, SUM( temp.payment_amount ) AS payment_amount, SUM( temp.invoice_amount ) AS invoice_amount FROM ( SELECT spo.id, spo.serial_number, IFNULL( spo.amount, 0 ) AS amount, spo.supplier_id, ( SELECT NAME FROM scm_supplier WHERE bool_delete_enum = 0 AND id = spo.supplier_id ) AS supplier_name, spo.settlement_status, ( SELECT amount FROM contract_supplier_settlement WHERE spo.id = order_id AND bool_delete_enum = 0 AND audit_status = 2 ) AS settlement_amount, (SELECT IFNULL( SUM( actually_payment_amount ), 0 ) FROM contract_supplier_payment WHERE property_type = 1 AND order_id = SPO.id AND bool_delete_enum = 0 AND audit_status = 2) AS payment_amount, ( SELECT IFNULL( SUM( invoice_amount ), 0 ) FROM contract_supplier_invoice WHERE property_type = 1 AND order_id = spo.id AND bool_delete_enum = 0 AND audit_status = 2 ) AS invoice_amount FROM scm_purchase_order AS spo WHERE spo.bool_delete_enum = 0
and spo.create_time >= #{startDate}
and spo.create_time <= #{endDate}
and spo.purchase_type = #{purchaseType}
) AS temp WHERE 1=1
and temp.payment_amount < ( CASE temp.settlement_status WHEN 0 THEN temp.amount ELSE temp.settlement_amount END )
and temp.payment_amount >= ( CASE temp.settlement_status WHEN 0 THEN temp.amount ELSE temp.settlement_amount END )
AND temp.invoice_amount < ( CASE temp.settlement_status WHEN 0 THEN temp.amount ELSE temp.settlement_amount END )
AND temp.invoice_amount >= ( CASE temp.settlement_status WHEN 0 THEN temp.amount ELSE temp.settlement_amount END )
AND temp.supplier_name like concat('%',#{supplierName},'%')
GROUP BY temp.supplier_id, temp.supplier_name

        SELECT IFNULL(SUM(amount),0)
        FROM scm_purchase_order
        WHERE bool_delete_enum = 0
        
            and create_time >= #{startDate}
        
        
            and create_time <= #{endDate}
        
        
            and supplier_id= #{supplierId}
        
        
            and branch_company_id = #{branchCompanyId}
        
        
            and purchase_type = #{purchaseType}

select
spo.*
from
scm_purchase_order spo
left join scm_supplier ss on ss.id=spo.supplier_id
left join sys_user u on spo.project_manager_id = u.id
where
spo.bool_delete_enum = 0
and spo.bool_temporary_storage = 0
and spo.data_status !=0

    and spo.basic_class & #{basicClass}


    and  spo.purchase_type = #{purchaseType}


    and #{materialType} & spo.basic_class


    and spo.purchase_status = #{purchaseStatus}


    and spo.serial_number like CONCAT('%', #{serialNumber},'%')


    
        and DATE_FORMAT(spo.create_time,'%Y-%m-%d') >= DATE_FORMAT(#{createTime[0]},'%Y-%m-%d')
    
    
        and DATE_FORMAT(spo.create_time,'%Y-%m-%d') <= DATE_FORMAT(#{createTime[1]},'%Y-%m-%d')
    


    and spo.settlement_status = #{settlementStatus}


    and spo.supplier_id = #{supplierId}


    and ss.name like CONCAT('%', #{supplierName},'%')


    and spo.applicant_name like CONCAT('%', #{applicantName},'%')


    and spo.branch_company_id = #{branchCompanyId}


    and (spo.last_operator_name like CONCAT('%', #{operatorName},'%') or spo.applicant_name like
    CONCAT('%',#{operatorName},'%'))


    and find_in_set(#{projectId},spo.project_ids)


    and spo.level = #{level}


    and spo.order_place = #{orderPlace}


    and spo.review_status = #{reviewStatus}


    and spo.data_status = #{dataStatus}


    and spo.bool_annual = #{boolAnnual}


    and spo.project_attribute in
    
        #{item}
    


    and u.name like concat('%',#{projectManagerName},'%')


    and spo.workshop_id = #{workshopId}


    and spo.bool_detail = #{boolDetail}


    
        and spo.amount >= #{purchaseAmount[0]}
    
    
        and spo.amount <= #{purchaseAmount[1]}

SELECT a.id as orderId, a.serial_number as purchaseContractNumber, a.material_type, a.settlement_status as settlementStatus, a.standing_book_is_print as standingBookIsPrint, b.short_name as contractSignBodyName FROM `scm_purchase_order` a LEFT JOIN sys_branch_company b on b.id = a.branch_company_id
WHERE a.bool_delete_enum = 0 AND a.project_attribute = 1 AND a.data_status = 2 AND a.review_status = 2
AND a.supplier_id = #{supplierId}
AND a.settlement_status = #{settlementStatus}
AND a.serial_number like CONCAT('%', #{serialNumber},'%')
AND a.basic_class & #{basicClass}
AND a.branch_company_id = #{branchCompanyId}
ORDER BY a.settlement_status ASC, a.id DESC

select * from scm_purchase_order where bool_delete_enum = 0 and bool_temporary_storage = 0 and data_status !=0 and review_status = 2
and supplier_id = #{supplierId}
and branch_company_id = #{branchCompanyId}
AND DATE_FORMAT(create_time, "%Y")=DATE_FORMAT(#{yearDate}, "%Y")

select * from scm_purchase_order
id in
#{item}

update scm_purchase_order
set bool_delete_enum = 0
where id = #{id}

SELECT *
FROM scm_purchase_order
where id = #{id}
